package com.hrms.attendance.repository;
import com.hrms.attendance.dto.AttendanceSearch;import com.hrms.attendance.model.AttendanceRecord;import org.springframework.data.domain.*;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.*;import org.springframework.stereotype.Repository;import java.util.Map;
@Repository public class AttendanceRepositoryImpl implements AttendanceRepositoryCustom {
 private static final Map<String,String> SORT=Map.of("workDate","workDate","employeeCode","employeeCodeSnapshot","status","attendanceStatus","createdAt","createdAt","lateMinutes","lateByMinutes","overtimeMinutes","overtimeMinutes"); private final MongoTemplate template;public AttendanceRepositoryImpl(MongoTemplate t){template=t;}
 public Page<AttendanceRecord> search(AttendanceSearch s){Criteria c=new Criteria();if(s.employeeId()!=null&&!s.employeeId().isBlank())c.and("employeeId").is(s.employeeId());if(s.employeeCode()!=null&&!s.employeeCode().isBlank())c.and("employeeCodeSnapshot").is(s.employeeCode().strip());if(s.departmentId()!=null&&!s.departmentId().isBlank())c.and("departmentIdSnapshot").is(s.departmentId());if(s.officeLocationId()!=null&&!s.officeLocationId().isBlank())c.and("officeSnapshot.officeLocationId").is(s.officeLocationId());if(s.shiftId()!=null&&!s.shiftId().isBlank())c.and("shiftSnapshot.shiftId").is(s.shiftId());if(s.status()!=null)c.and("attendanceStatus").is(s.status());if(s.fromDate()!=null||s.toDate()!=null){if(s.fromDate()!=null)c.and("workDate").gte(s.fromDate());if(s.toDate()!=null)c.and("workDate").lte(s.toDate());}Sort.Direction d="asc".equalsIgnoreCase(s.sortDirection())?Sort.Direction.ASC:Sort.Direction.DESC;Pageable p=PageRequest.of(s.page(),s.limit(),Sort.by(d,SORT.getOrDefault(s.sortBy(),"workDate")));return new PageImpl<>(template.find(Query.query(c).with(p),AttendanceRecord.class),p,template.count(Query.query(c),AttendanceRecord.class));}
}
